import export_mfoil_fixtures as ex
from export_mfoil_fixtures import mf

# generated by running the fixed mfoil at npanel=120, Re=1e6, ncrit=9 (Xt = transition x, [lower, upper];
# 0 means the surface stays laminar to the trailing edge)
GOLDEN = {
    'naca2412_a2': dict(cl=0.4488381373498545, cd=0.005747737579317297, cm=-0.04790669408635424,
                        Xt=[0.9649842502428518, 0.5260113017385367]),
    'naca2412_a10': dict(cl=1.2615771978391102, cd=0.01546664276433979, cm=-0.03674416068252326,
                         Xt=[0.0, 0.031580015950410635]),
    'naca4412_blunt_a4': dict(cl=0.9444040986122336, cd=0.007697334011116903, cm=-0.10981141199853531,
                              Xt=[0.0, 0.4648893126157657]),
    'naca2412_a4_M03': dict(cl=0.7605519112482562, cd=0.007254401135421676, cm=-0.05992929843521698,
                            Xt=[0.0, 0.3713162951456922]),
    'naca2412_sharp_a4': dict(cl=0.7259856581983329, cd=0.006965814601826217, cm=-0.059317238050763,
                              Xt=[0.9967978962743242, 0.3953318683344035]),
    'naca2412_closed_a4': dict(cl=0.7256027833775518, cd=0.006969420347660172, cm=-0.059229854272085034,
                               Xt=[0.996606145747988, 0.39551352674524104]),
}

# warm-started sweep (initbl=False after a converged point): alpha -> cl, cd, cm, Xt, Newton iterations;
# cold starts at 4 and 8 deg do not converge at this paneling
GOLDEN_SWEEP = {
    0.0: (0.2346093659880516, 0.005623955224451639, -0.05141186154259765, [0.6771779970995477, 0.6516979642667003], 17),
    2.0: (0.4488381373475846, 0.005747737579163307, -0.04790669408576068, [0.9649842502473998, 0.5260113017318252], 16),
    4.0: (0.7221418822428155, 0.006932341440764239, -0.058917508116226244, [0.9975395825114202, 0.39563376555786217], 10),
    6.0: (0.9033009161494397, 0.009000536178333145, -0.050783936130311985, [0.0, 0.2122310374463296], 15),
    8.0: (1.0840711690491172, 0.012165465977736574, -0.043670704685155735, [0.0, 0.06762414177328226], 13),
}


@pytest.fixture(scope='module')
def fresh():
    return ex.build_all()  # six staged viscous solves (~50 s)


def solve(alpha, visc=True, npanel=120, **geom):
    m = mf.mfoil(npanel=npanel, **geom)
    m.param.verb = 0
    if visc:
        m.setoper(alpha=alpha, Re=1e6, Ma=0.0)
    else:
        m.setoper(alpha=alpha)
    m.solve()
    return m


@pytest.mark.parametrize('name', list(GOLDEN))
def test_golden_values(fresh, name):
    f, g = fresh[name + '.json']['final'], GOLDEN[name]
    assert f['converged']
    for k in ('cl', 'cd', 'cm'):
        assert f[k] == pytest.approx(g[k], rel=1e-6)
    assert np.array(f['Xt']['data'])[:, 1] == pytest.approx(g['Xt'], rel=1e-6, abs=1e-9)


def test_golden_warm_sweep(fresh):
    pts = fresh['naca2412_sweep.json']['points']
    assert [p['alpha'] for p in pts] == list(GOLDEN_SWEEP)
    for p in pts:
        cl, cd, cm, xt, its = GOLDEN_SWEEP[p['alpha']]
        assert p['converged'] and p['newton_iterations'] == its
        assert [p['cl'], p['cd'], p['cm']] == pytest.approx([cl, cd, cm], rel=1e-6)
        assert np.array(p['Xt']['data'])[:, 1] == pytest.approx(xt, rel=1e-6, abs=1e-9)


def test_coords_path_matches_naca_path():
    a = mf.mfoil(naca='2412', npanel=120)
    b = mf.mfoil(coords=ex.naca_coords('2412'), npanel=120)
    assert np.array_equal(a.foil.x, b.foil.x) and np.array_equal(a.foil.s, b.foil.s)


def assert_close(a, b, path=''):
    if isinstance(a, dict):
        assert a.keys() == b.keys(), path
        for k in a:
            assert_close(a[k], b[k], f'{path}.{k}')
    elif isinstance(a, list):
        assert len(a) == len(b), path
        for i, (x, y) in enumerate(zip(a, b)):
            assert_close(x, y, f'{path}[{i}]')
    elif isinstance(a, float) or isinstance(b, float):
        assert a == pytest.approx(b, rel=1e-9, abs=1e-12), path
    else:
        assert a == b, path


def test_committed_fixtures_match_fresh_export(fresh):
    for fname, obj in fresh.items():
        path = os.path.join(ex.OUT_DIR, fname)
        assert os.path.exists(path), f'missing {path}; run python tests/export_mfoil_fixtures.py'
        with open(path, encoding='utf-8') as fh:
            committed = json.load(fh)
        committed.pop('meta'); obj = dict(obj); obj.pop('meta')
        assert_close(json.loads(ex.dumps(obj)), committed, fname)


def test_te_closed_to_roundoff_solves(fresh):
    # TE closed to ~3e-17 with upper below lower (used to fail 'Wrong wake direction'); set_coords opens
    # it to the same 1e-4 gap as the exactly repeated TE point, so the result matches that case
    m = solve(4.0, coords=ex.naca_coords('2412', c4=-0.1036))
    ref = fresh['naca2412_closed_a4.json']['final']
    assert m.glob.conv
    for k in ('cl', 'cd', 'cm'):
        assert getattr(m.post, k) == pytest.approx(ref[k], rel=1e-8)


def test_symmetric_airfoil_zero_alpha():
    # npanel=121: with 120 the LE node sits exactly on the stagnation point and Newton stalls at Rnorm ~5e-9
    m = solve(0.0, naca='0012', npanel=121)
    assert m.glob.conv
    assert abs(m.post.cl) < 1e-8 and abs(m.post.cm) < 1e-8
    assert m.vsol.Xt[0, 1] == pytest.approx(m.vsol.Xt[1, 1], rel=1e-6)


def test_mirrored_airfoil(fresh):
    ref = fresh['naca2412_a2.json']['final']
    X = np.array(fresh['naca2412_a2.json']['input']['coords']['data'])
    X[1] *= -1  # mirror; also reverses the orientation, exercising set_coords' flip
    m = solve(-2.0, coords=X)
    assert m.glob.conv
    assert m.post.cl == pytest.approx(-ref['cl'], rel=1e-6)
    assert m.post.cm == pytest.approx(-ref['cm'], rel=1e-6)
    assert m.post.cd == pytest.approx(ref['cd'], rel=1e-6)


def test_inviscid_lift_slope_thin_airfoil():
    m = solve(2.0, visc=False, naca='0006')
    slope = m.post.cl / np.radians(2.0)
    assert 2 * np.pi <= slope <= 1.1 * 2 * np.pi  # thickness raises it ~5% above thin-airfoil 2*pi


def test_ping_derivatives(capsys):
    m = mf.mfoil(naca='2412', npanel=120)
    mf.ping_test(m)
    out = capsys.readouterr().out
    # closure/residual_station pings: every component must converge at ~2nd order unless its error is roundoff-level
    lines = re.findall(r'^(\S+)\s+(lam|turb|wake)\s+err=\[(.*?)\]\s+rates=\[(.*?)\]', out, re.M)
    assert len(lines) == 2 * 3 * 18
    for name, kind, errs, rates in lines:
        for e, r in zip(re.findall(r'(\S+)->\S+', errs), rates.split()):
            assert r == 'N/A' or float(r) >= 1.5 or float(e) < 1e-8, (name, kind, errs, rates)
    rates = dict(re.findall(r'^(.*) ping error convergence rate = (\S+)', out, re.M))
    for k in ('transition residual', 'stagnation residual', 'wake system', 'stagnation state', 'lift calculation'):
        assert float(rates[k]) > 1.9, k
    # global system: pre-asymptotic at ping_test's step (dU ~ U(0,1) on th, ds ~ 1e-3), reaches ~2 at smaller steps
    for k in ('global system, ix=0', 'global system, ix=1'):
        assert float(rates[k]) > 1.3, k
